#[ignore]
fn armstrong_number_containing_seven_zeroes() {
    assert!(is_armstrong_number(186_709_961_001_538_790_100_634_132_976_990));
}

#[test]
#[ignore]
fn the_largest_and_last_armstrong_number() {
